#!/usr/bin/env node
/**
 * Expand key_figures.csv and creatures.csv to cover major entities across all 25 works.
 */

const fs = require('fs');
const path = require('path');

const LEXICON_DIR = path.join(__dirname, '../Corpus Forge/lexicons');
const FIGURES_FILE = path.join(LEXICON_DIR, 'key_figures.csv');
const CREATURES_FILE = path.join(LEXICON_DIR, 'creatures.csv');

function csvEscape(val) {
  const str = String(val || '').replace(/"/g, '""');
  if (str.includes(',') || str.includes('"') || str.includes('\n')) {
    return `"${str}"`;
  }
  return str;
}

function readExistingIds(filePath) {
  if (!fs.existsSync(filePath)) return new Set();
  const lines = fs.readFileSync(filePath, 'utf8').split('\n');
  const ids = new Set();
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    // Simple parse: first field before first comma (handle quotes)
    const m = line.match(/^"?([^",]+)/);
    if (m) ids.add(m[1]);
  }
  return ids;
}

function appendRows(filePath, rows, headers) {
  const content = rows.map((r) => r.map(csvEscape).join(',')).join('\n');
  if (!fs.existsSync(filePath)) {
    fs.writeFileSync(filePath, `${headers}\n${content}\n`, 'utf8');
  } else {
    const existing = fs.readFileSync(filePath, 'utf8').trimEnd();
    fs.writeFileSync(filePath, `${existing}\n${content}\n`, 'utf8');
  }
}

const existingFigureIds = readExistingIds(FIGURES_FILE);
const existingCreatureIds = readExistingIds(CREATURES_FILE);

const newFigures = [];
const newCreatures = [];

function addFigure(id, name, type, culture, domains, aliases, desc, notes, works, archetypes, functions, cognitive) {
  if (existingFigureIds.has(id)) return;
  newFigures.push([id, name, type, culture, domains, aliases, desc, notes, works, archetypes, functions, cognitive]);
  existingFigureIds.add(id);
}

function addCreature(id, name, culture, type, desc, symbolism, aliases, notes, works) {
  if (existingCreatureIds.has(id)) return;
  newCreatures.push([id, name, culture, type, desc, symbolism, aliases, notes, works]);
  existingCreatureIds.add(id);
}

